package dev.forgesworn.kithmoot.vectors

import dev.forgesworn.kithmoot.crypto.Schnorr
import dev.forgesworn.kithmoot.crypto.hexToBytes
import dev.forgesworn.kithmoot.protocol.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test

/** Verbatim published Fold vectors (v0.17.0 plus the version 7 `short` group), not generated by this client. */
class NodeRoomVectorsTest {
    private val vector = Json.parseToJsonElement(requireNotNull(javaClass.getResource("/node-room-vectors.json")).readText()).jsonObject
    private val now = vector.getValue("now").jsonPrimitive.long
    private val keys = vector.getValue("keys").jsonObject
    private fun key(name: String) = keys.getValue(name).jsonPrimitive.content.hexToBytes()
    private val descriptor = vector.getValue("descriptor").jsonObject
    private val node = requireNotNull(NodeRooms.read(descriptor, now))
    private val request = vector.getValue("request").jsonObject
    private val requestEvent = request.getValue("event")
    private val requestId = request.getValue("requestId").jsonPrimitive.content
    private val requestEnd = request.getValue("expiresAt").jsonPrimitive.long
    private val operation = "ab".repeat(16)
    private fun entropy(name: String, source: JsonObject = vector): () -> ByteArray {
        val values = source.getValue(name).jsonArray.map { it.jsonPrimitive.content.hexToBytes() }
        var index = 0
        return { require(index < values.size) { "Unexpected entropy request" }; values[index++].copyOf() }
    }

    private fun sizedEntropy(name: String): (Int) -> ByteArray {
        val next = entropy(name)
        return { size -> next().also { require(it.size == size) { "Wrong entropy request size" } } }
    }

    @Test fun readsAndReproducesTheSignedRecordAndAskOnlyLinkExactly() {
        assertEquals("node-room/1", vector.getValue("profile").jsonPrimitive.content)
        assertEquals(deriveRoom(key("secret")).roomId, node.room)
        assertEquals(Schnorr.publicKeyHex(key("authority")), node.authority)
        assertEquals(descriptor, NodeRooms.sign(key("authority"), node.room, node.origin, node.serviceKey, now, random = entropy("descriptorRandom")).toJson())
        val link = vector.getValue("link").jsonPrimitive.content
        assertEquals(descriptor, requireNotNull(NodeRooms.parseLink(link, now)).wire)
        assertEquals(link, NodeRooms.encodeLink("https://app.example/j/", descriptor, now))
        assertTrue(runCatching { decodeJoinUrl(link) }.isFailure)
        assertEquals(listOf("turn:node.example:3478?transport=udp", "turn:node.example:3478?transport=tcp", "turns:node.example:5349?transport=tcp", "turns:turn.node.example:443?transport=tcp"), node.turnUrls)
    }

    @Test fun readsAndWritesTheVersion7LinksAsTheIdenticalSignedRecords() {
        val short = vector.getValue("short").jsonObject; val base = "https://app.example/j/"
        fun text(o: JsonObject, name: String) = o.getValue(name).jsonPrimitive.content
        val custom = vector.getValue("customPorts").jsonObject
        assertEquals(7, short.getValue("linkVersion").jsonPrimitive.int)
        assertEquals(descriptor, requireNotNull(NodeRooms.parseLink(text(short, "link"), now)).wire)
        assertEquals(custom.getValue("descriptor"), requireNotNull(NodeRooms.parseLink(text(short, "customPortsLink"), now)).wire)
        assertEquals(text(short, "link"), NodeRooms.encodeShortLink(base, descriptor, now))
        assertEquals(text(short, "customPortsLink"), NodeRooms.encodeShortLink(base, custom.getValue("descriptor").jsonObject, now))
        val existing = short.getValue("existing").jsonObject; val record = existing.getValue("descriptor").jsonObject
        val endsAt = existing.getValue("endsAt").jsonPrimitive.long; val policy = existing.getValue("policy").jsonObject
        val parsed = requireNotNull(NodeRooms.parseLink(text(existing, "link"), now))
        assertEquals(record, parsed.wire)
        assertEquals(NodeExistingRoomPolicy(true, policy), parsed.existing); assertEquals(endsAt, parsed.endsAt)
        assertEquals(text(existing, "link"), NodeRooms.encodeShortLink(base, record, now))
        assertEquals(text(existing, "longLink"), NodeRooms.longLink(text(existing, "link"), now))
        assertEquals(record, NodeRooms.sign(key("authority"), parsed.room, parsed.origin, parsed.serviceKey, now, endsAt, entropy("descriptorRandom", existing),
            NodeTurnPorts(34790, 53499), NodeExistingRoomPolicy(true, policy)).toJson())
        for (state in short.getValue("states").jsonArray.map { it.jsonObject }) {
            val at = state.getValue("now").jsonPrimitive.long
            val expected = when (text(state, "state")) {
                "open" -> NodeRoomLinkState.Open(requireNotNull(NodeRooms.read(record, at)))
                "ended" -> NodeRoomLinkState.Ended(state.getValue("endsAt").jsonPrimitive.long)
                else -> NodeRoomLinkState.Early(state.getValue("createdAt").jsonPrimitive.long)
            }
            assertEquals("at $at", expected, NodeRooms.inspectLink(text(existing, "link"), at))
        }
        for (link in listOf(text(short, "link"), text(short, "customPortsLink"), text(existing, "link"))) assertTrue(runCatching { decodeJoinUrl(link) }.isFailure)
    }

    @Test fun reproducesPublishedCustomPortsRecordAndLinkWithTheSameDefaultWire() {
        val custom = vector.getValue("customPorts").jsonObject
        val record = custom.getValue("descriptor").jsonObject
        val parsed = requireNotNull(NodeRooms.read(record, now))
        val ports = NodeTurnPorts(34790, 53499)
        assertEquals(ports, parsed.turnPorts)
        assertEquals(custom.getValue("iceUrls").jsonArray.map { it.jsonPrimitive.content }, parsed.iceUrls)
        assertEquals(custom.getValue("turnUrls").jsonArray.map { it.jsonPrimitive.content }, parsed.turnUrls)
        assertEquals(record, NodeRooms.sign(key("authority"), parsed.room, parsed.origin, parsed.serviceKey, now,
            random = entropy("descriptorRandom", custom), turnPorts = ports).toJson())
        val link = custom.getValue("link").jsonPrimitive.content
        assertEquals(record, requireNotNull(NodeRooms.parseLink(link, now)).wire)
        assertEquals(link, NodeRooms.encodeLink("https://app.example/j/", record, now))
        assertEquals(descriptor, NodeRooms.sign(key("authority"), node.room, node.origin, node.serviceKey, now,
            random = entropy("descriptorRandom"), turnPorts = NodeTurnPorts.DEFAULT).toJson())
    }

    @Test fun rejectsMalformedPortProfilesEvenInsideAnOtherwiseValidSignature() {
        val invalid = listOf(JsonNull, buildJsonObject { put("udpTcp", 34790) },
            buildJsonObject { put("udpTcp", 443); put("tls", 53499) },
            buildJsonObject { put("udpTcp", 34790); put("tls", 34790) },
            buildJsonObject { put("udpTcp", "34790"); put("tls", 53499) },
            buildJsonObject { put("udpTcp", 4294970774L); put("tls", 53499) },
            buildJsonObject { put("udpTcp", 34790); put("tls", 53499); put("other", true) })
        for (ports in invalid) {
            assertNull(NodeRooms.readTurnPorts(ports))
            val body = JsonObject(Json.parseToJsonElement(node.event.content).jsonObject + ("turnPorts" to ports))
            val signed = Events.sign(key("authority"), NODE_RECORD_KIND, now, node.event.tags, body.toString(), ByteArray(32) { 1 })
            assertNull(NodeRooms.read(signed.toJson(), now))
        }
        assertEquals(NodeTurnPorts.DEFAULT, NodeRooms.readTurnPorts(null))
    }

    @Test fun decryptsAndReproducesThePublishedGuestRequest() {
        val decoded = requireNotNull(NodeAdmissions.readRequest(node, key("authority"), requestEvent, now))
        assertEquals(requestId, decoded.id); assertEquals(requestEnd, decoded.expiresAt)
        assertEquals(Schnorr.publicKeyHex(key("device")), decoded.device)
        assertEquals(Schnorr.publicKeyHex(key("participant")), decoded.participant)
        assertEquals(vector.getValue("credential"), decoded.credential)
        val encoded = NodeAdmissions.request(node, key("device"), decoded.credential, now, decoded.name, sizedEntropy("requestRandom"))
        assertEquals(requestId, encoded.requestId); assertEquals(requestEnd, encoded.expiresAt); assertEquals(requestEvent, encoded.event.toJson())
    }

    @Test fun decryptsAndReproducesTheGrantedAndDeniedAnswersWithoutLosingFields() {
        val allowed = NodeAdmissions.readAnswer(node, key("device"), vector.getValue("answer"), requestId, requestEnd, now) as NodeRoomAdmission
        assertArrayEquals(key("secret"), allowed.secret); assertEquals(vector.getValue("grant"), allowed.grant)
        assertTrue(allowed.destruct); assertTrue(allowed.persistent); assertEquals(0, allowed.epoch)
        assertEquals(listOf(node.relay), allowed.relays)
        assertEquals(vector.getValue("answer"), NodeAdmissions.answer(node, key("authority"), requestEvent, vector.getValue("answer").jsonObject.getValue("created_at").jsonPrimitive.long,
            NodeAdmissionGrant(allowed.secret, allowed.epochHint, allowed.grant), sizedEntropy("answerRandom")).toJson())
        assertEquals(NodeJoinDenied, NodeAdmissions.readAnswer(node, key("device"), vector.getValue("denied"), requestId, requestEnd, now))
        assertEquals(vector.getValue("denied"), NodeAdmissions.answer(node, key("authority"), requestEvent, vector.getValue("denied").jsonObject.getValue("created_at").jsonPrimitive.long, random = sizedEntropy("deniedRandom")).toJson())
        assertFalse(allowed.toString().contains(keys.getValue("secret").jsonPrimitive.content))
    }

    @Test fun verifiesAndReproducesExplicitClosureAndEncryptedRetirement() {
        val closure = vector.getValue("closure")
        assertEquals(closure, NodeRooms.signClosure(node, key("authority"), operation, now, entropy("closureRandom")).toJson())
        assertEquals(vector.getValue("closureProof"), requireNotNull(NodeRooms.readClosure(closure, node, now)).toJson())
        assertEquals(closure, requireNotNull(NodeRooms.recoverClosure(vector.getValue("closureProof"), node, now)).toJson())
        assertEquals(operation to now, NodeRooms.readRetirement(vector.getValue("retirement"), node, key("secret"), now))
        assertEquals(vector.getValue("retirement"), NodeRooms.signRetirement(node, key("authority"), key("secret"), operation, now, entropy("retirementRandom")).toJson())
        assertNull(NodeRooms.readRetirement(vector.getValue("retirement"), node, ByteArray(32) { 9 }, now))
    }

    @Test fun verifiesCompletionAfterWipeUsingOnlyPublicServiceAndOperation() {
        val receipt = requireNotNull(NodeRooms.receipt(vector.getValue("receipt"), node.serviceKey, operation, now))
        assertEquals(3L, receipt.eventsDeleted); assertEquals(now, receipt.completedAt)
        assertTrue(receipt.callsRevoked && receipt.relayPurged && receipt.published)
        assertNull(NodeRooms.receipt(vector.getValue("receipt"), node.authority, operation, now))
        assertNull(NodeRooms.receipt(vector.getValue("receipt"), node.serviceKey, "cd".repeat(16), now))
        assertNull(NodeRooms.readClosure(vector.getValue("receipt"), node, now))
    }

    @Test fun refusesWrongRequestDeviceNodeTamperingExpiryAndForgedGrant() {
        assertEquals(7, vector.getValue("refusals").jsonArray.size)
        assertNull(NodeAdmissions.readAnswer(node, key("device"), vector.getValue("answer"), "ff".repeat(32), requestEnd, now))
        assertNull(NodeAdmissions.readAnswer(node, ByteArray(32) { 8 }, vector.getValue("answer"), requestId, requestEnd, now))
        val foreign = requireNotNull(NodeRooms.read(NodeRooms.sign(key("authority"), node.room, "https://other.example", node.serviceKey, now).toJson(), now))
        assertNull(NodeAdmissions.readAnswer(foreign, key("device"), vector.getValue("answer"), requestId, requestEnd, now))
        assertNull(NodeRooms.read(JsonObject(descriptor + ("content" to JsonPrimitive(node.event.content + " "))), now))
        assertNull(NodeAdmissions.readAnswer(node, key("device"), vector.getValue("answer"), requestId, requestEnd, now + 91))
        val grant = vector.getValue("grant").jsonObject
        assertFalse(NodeRooms.verifyGrant(JsonObject(grant + ("sig" to JsonPrimitive("00".repeat(64)))), node, Schnorr.publicKeyHex(key("device")), now))
        assertFalse(NodeRooms.verifyGrant(grant, node, node.authority, now))
        assertNull(NodeRooms.readClosure(grant, node, now))
    }

    @Test fun refusesAmbiguousRecordsAndKeepsExpirationInsideTheSignedEnd() {
        assertNull(NodeRooms.read(JsonObject(descriptor + ("extra" to JsonPrimitive(true))), now))
        assertNull(NodeRooms.read(descriptor, now, Schnorr.publicKeyHex(key("device"))))
        for (origin in listOf("http://node.example", "https://127.0.0.1", "https://node.local", "https://node.home", "https://node.example:443", "https://node.example/", "https://user@node.example")) {
            assertTrue(origin, runCatching { NodeRooms.sign(key("authority"), node.room, origin, node.serviceKey, now) }.isFailure)
        }
        assertEquals(listOf(listOf("expiration", (now + 60).toString())), NodeRooms.expiration(emptyList(), now, now + 60))
        assertEquals(listOf(listOf("expiration", (now + 30).toString())), NodeRooms.expiration(listOf(listOf("expiration", (now + 30).toString())), now, now + 60))
        assertEquals(listOf(listOf("expiration", (now + NODE_HORIZON_SECONDS).toString())), NodeRooms.expiration(emptyList(), now))
    }
}
